"""Publish isolated pilot review; no API requests."""
import importlib.util,collections,json,html
from pathlib import Path
HERE=Path(__file__).resolve().parent
spec=importlib.util.spec_from_file_location('pilot',HERE/'pilot.py');p=importlib.util.module_from_spec(spec);spec.loader.exec_module(p);c=p.c
rows=c.load(HERE/'selection.json');manifest=c.load(HERE/'manifest.json');records=[r for f in sorted((HERE/'responses').glob('*.validated.json')) for r in c.load(f)]
assert len(records)==len({r['id'] for r in records})==200
assert {r['id'] for r in records}=={q['id'] for q in rows}
byid={r['id']:r for r in records}
# Explicit reviewer corrections retain original model assessment.
corrections={
'otqa:f95615125c6ca3c918098c6e':dict(translationStatus='needs-repair',reason='«літаючий трапеціо» is malformed Ukrainian; name checks are also pending.'),
'otqa:93b3961fd92afa74d2194b69':dict(translationStatus='needs-repair',reason='Wilde appears as both Вайлд and Вайльд in the same prompt; standardize after name verification.'),
'otqa:21dc3a09bf02c304d63dd922':dict(reason='Residual US/Canadian MLB team trivia should be held out of Fun; previous semantic tagging missed league specificity.',recommendedAction='exclude-from-fun'),
'otqa:e1f621f9d480c0df43e0ccf2':dict(reason='US cable-station rerun details are niche audience-specific trivia.',recommendedAction='exclude-from-fun'),
'otqa:8a334ab415892a4a04929440':dict(reason='Celebrity surgery detail conflicts with the intended casual Fun pool.',recommendedAction='exclude-from-fun')}
for qid,change in corrections.items():
    r=byid[qid];r['reviewerNote']=change['reason'];r['reviewerAction']=change.get('recommendedAction','review')
    if 'translationStatus' in change:r['modelTranslationStatus']=r['translationStatus'];r['translationStatus']=change['translationStatus']
checks=[dict(id='otqa:95855dd6104c164499e6b6aa',scope='Ukrainian spelling of Ingolstadt only; does not verify other choices or the entire question',finding='Інгольштадт matches Audi Ukrainian primary material.',url='https://media.audi.com/is/content/audi/country/de/de/rechtliches/betroffenenrechte/erprobungsfahrzeuge/Privacy-Policy_Ukrainisch.pdf'),dict(id='otqa:56e6dedbe276694c96bf0f8d',scope='Country/capital names and keyed capital only; other distractors not verified',finding='Бахрейн / Манама supported by Encyclopedia of Modern Ukraine.',url='https://esu.com.ua/article-41305'),dict(id='otqa:21dc3a09bf02c304d63dd922',scope='English MLB event identity; NOT Ukrainian player-name spelling verification',finding='MLB primary source identifies Len Barker and the 15 May 1981 event, confirming residual league trivia.',url='https://www.mlb.com/braves/video/bb-moments-barker-s-perfecto-c3235117')]
for r in records:r['sourceChecks']=[x for x in checks if x['id']==r['id']]
ledger=c.load(HERE/'ledger.json');assert all(x['status']=='completed' for x in ledger['requests'].values());cost=sum(x['costUsd'] for x in ledger['requests'].values())
assert c.digest(c.load(p.ROOT/'question-bank/questions.json'))==manifest['bankSha256'];assert __import__('hashlib').sha256((p.ROOT/'browser-site/dist/questions.json').read_bytes()).hexdigest()==manifest['runtimeSha256']
summary=dict(questions=200,sourcePool=7104,categories=len(manifest['perCategory']),difficulty=dict(sorted(collections.Counter(r['difficultyStars'] for r in records).items())),readingBurden=dict(collections.Counter(r['readingBurden'] for r in records)),translationStatus=dict(collections.Counter(r['translationStatus'] for r in records)),withSourceConcerns=sum(bool(r['sourceConcerns']) for r in records),entityPairs=sum(len(r['entities']) for r in records),withheldEntityPairs=sum(len(r['withheldEntities']) for r in records),targetedExternalChecks=len(checks),reviewerCorrections=len(corrections),costUsd=cost,projectedSameModelPass7104Usd=cost/200*7104,bankUnchanged=True)
c.write(HERE/'assessment.json',dict(backendOnly=True,model=c.MODEL,records=records));c.write(HERE/'summary.json',summary);c.write(HERE/'source-checks.json',checks)
items=[dict(**q,assessment=byid[q['id']]) for q in rows]
page='''<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TriviTV · Quality pilot 200</title><style>body{background:#f3f6f3;color:#243c3b;font:16px/1.5 system-ui;margin:0}main{max-width:1280px;margin:auto;padding:24px}header,article{background:white;border:1px solid #d7e2df;border-radius:12px;padding:22px;margin-bottom:18px}h1,h2,h3{margin:0 0 10px}.pair{display:grid;grid-template-columns:1fr 1fr;gap:24px}.choice{border:1px solid #dde5e3;padding:5px 10px;margin:5px 0;border-radius:5px}.correct{background:#e4f2e9}.badge{display:inline-block;background:#edf0f8;border-radius:6px;padding:4px 9px;margin:4px}select,input,button{font:inherit;padding:9px;border:1px solid #b8cbc4;border-radius:6px;max-width:100%}.filters{display:flex;gap:10px;flex-wrap:wrap}small{color:#627570}article{overflow-wrap:anywhere}a{color:#14736d}li{margin-bottom:6px}.warn{background:#fff3df;padding:12px;border-radius:6px}@media(max-width:700px){main{padding:12px}.pair{grid-template-columns:1fr}}</style><main><header><h1>Question quality · 200-question pilot</h1><p id="summary"></p><p>Difficulty estimates target general Ukrainian adults. Reading burden is separate. Translation “pass” means no issue detected by the model; it does not mean facts or names are externally verified. Only three targeted checks have sources. Rare categories are oversampled: do not extrapolate these percentages to the full bank.</p><p><a href="REPORT.md">Report</a> · <a href="assessment.json">Assessments JSON</a> · <a href="source-checks.json">Source checks</a></p><div class="filters"><select id="status"><option value="">All translation statuses</option><option>pass</option><option>needs-repair</option><option>needs-source-verification</option></select><select id="stars"><option value="">All difficulties</option>STARS</select><input id="search" placeholder="Search question / ID / assessment" aria-label="Search"></div></header><p id="count"></p><button id="prev">Previous</button> <button id="next">Next</button><div id="cards"></div></main><script type="application/json" id="data">DATA</script><script>
const rows=JSON.parse(document.getElementById('data').textContent),s=SUMMARY,$=id=>document.getElementById(id),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let page=0;
$('summary').textContent=`200 questions · 19 categories · $${s.costUsd.toFixed(4)} API cost · live bank unchanged`;
function choices(q,k){return q.choices.map((v,i)=>`<div class="choice ${i===k?'correct':''}">${'ABCD'[i]}. ${esc(v)} ${i===k?'✓':''}</div>`).join('')}
function render(){const term=$('search').value.toLowerCase(),filtered=rows.filter(q=>(!$('status').value||q.assessment.translationStatus===$('status').value)&&(!$('stars').value||q.assessment.difficultyStars===+$('stars').value)&&(!term||JSON.stringify(q).toLowerCase().includes(term)));page=Math.min(page,Math.max(0,Math.ceil(filtered.length/20)-1));$('count').textContent=`${filtered.length? page*20+1:0}–${Math.min(filtered.length,page*20+20)} of ${filtered.length}`;$('prev').disabled=!page;$('next').disabled=(page+1)*20>=filtered.length;$('cards').innerHTML=filtered.slice(page*20,page*20+20).map(q=>{const a=q.assessment;return `<article><h2>${esc(q.category)}</h2><small>${esc(q.id)}</small><p><span class="badge">${'★'.repeat(a.difficultyStars)}${'☆'.repeat(5-a.difficultyStars)}</span><span class="badge">Reading: ${esc(a.readingBurden)}</span><span class="badge">${esc(a.translationStatus)}</span></p><div class="pair"><section><h3>English</h3><p>${esc(q.text)}</p>${choices(q,q.correct)}</section><section><h3>Українська</h3><p>${esc(q.ukrainian.text)}</p>${choices(q.ukrainian,q.correct)}</section></div><p><b>Difficulty:</b> ${esc(a.difficultyReason)} (${esc(a.difficultyConfidence)} confidence)</p><p><b>Reading:</b> ${esc(a.readingReason)}</p><p><b>Translation:</b> ${esc(a.translationReason)}</p>${a.reviewerNote?`<p class="warn"><b>Reviewer:</b> ${esc(a.reviewerNote)} · ${esc(a.reviewerAction)}</p>`:''}<ul>${a.issues.map(i=>`<li><b>${esc(i.kind)}:</b> ${esc(i.explanation)}<br>EN: ${esc(i.englishEvidence)} / UA: ${esc(i.ukrainianEvidence)}${i.suggestedRepair?'<br>Suggested repair: '+esc(i.suggestedRepair):''}</li>`).join('')}</ul>${a.sourceConcerns.length?'<p class="warn">Source concerns: '+a.sourceConcerns.map(esc).join('; ')+'</p>':''}<details><summary>${a.entities.length} name / term pairs · ${a.withheldEntities.length} withheld non-exact pairs</summary><ul>${a.entities.map(e=>`<li>${esc(e.english)} → ${esc(e.ukrainian)} (${esc(e.role)}) · ${esc(e.assessment)} — ${esc(e.reason)}</li>`).join('')}</ul></details>${a.sourceChecks.map(c=>`<p><a href="${esc(c.url)}">External source check</a>: ${esc(c.finding)}<br><small>Scope: ${esc(c.scope)}</small></p>`).join('')}</article>`}).join('')}
for(const id of ['status','stars','search'])$(id).addEventListener(id==='search'?'input':'change',()=>{page=0;render()});$('prev').onclick=()=>{page--;render();window.scrollTo(0,0)};$('next').onclick=()=>{page++;render();window.scrollTo(0,0)};render();</script>'''
page=page.replace('STARS',''.join(f'<option value="{i}">{i} stars</option>' for i in range(1,6))).replace('DATA',json.dumps(items,ensure_ascii=False).replace('<','\\u003c')).replace('SUMMARY',json.dumps(summary))
(HERE/'review.html').write_text(page,encoding='utf-8')
(HERE/'REPORT.md').write_text('# Quality pilot — 200 questions\n\n'+json.dumps(summary,indent=2)+'\n\nSelection: up to five per remaining category, then shuffled remainder. All19categories covered, rare categories oversampled; rates are not representative population prevalence. Scores are model estimates, not player-calibrated. Original model outputs and reviewer corrections preserved separately. Names/terms have exact role-specific bilingual spans; invalid spans withheld. Three targeted external checks verify only their explicitly stated scopes; remaining names are unverified. Translation pass does not approve source factual quality.\n\nReviewer found residual MLB/cable-TV/celebrity-detail content despite prior filters. Suggested grammar repairs include дві яблука→два яблука, літаючий трапеціо→літальна трапеція (terminology still needs verification), Нафтовий свердловина→Нафтова свердловина. No repairs/scores applied to Main, Fun membership, runtime, APK or live service.\n\nCost projection is only the same automated pass, assumes equal tokens per question and current recorded rates; excludes external research and later review. No repeat-run consistency or independent accuracy study performed.\n',encoding='utf-8')
print(c.stable(summary))
